INSERT OR IGNORE INTO planner_modules (id,module_code,name,description,purpose,functional_requirements,acceptance_criteria,status,priority,owner_name,target_release,risk_level,progress,approval_state,created_by,created_at,updated_at)
VALUES ('module-donor-crm','GR-CRM','Donor CRM','Organization-scoped donor relationship management sharing the canonical supporter records with Email Marketing.','Give nonprofits one place to manage donor identity, giving, households, tasks, opportunities, preferences, and follow-up.','Contact table and drawer; search/filter/export/import; household records; giving and activity history; notes and tasks; opportunities; pledges and exceptions; preferences; duplicate review; private attachments; factual reports.','Authorized organizers can manage CRM records without duplicating contacts or financial ledgers; organization isolation and audit history are enforced; Email Marketing reuses CRM contacts and consent.','In Progress','Critical','Gather Product','Sandbox','High',72,'Approved','system',1795086400000,1795086400000);

INSERT OR IGNORE INTO planner_features (id,module_id,name,description,functional_specification,acceptance_criteria,status,approval_state,created_by,created_at,updated_at) VALUES
('crm-feature-contacts','module-donor-crm','Contacts and donor drawer','Searchable contact table with persistent right-side profile.','Support real contact fields, roles, tags, giving summaries, activity tabs, segments, preferences, and list-context preservation.','Selecting a contact does not navigate away or reset search and filters.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-households','module-donor-crm','Households and affiliations','Households, primary contacts, relationships, companies, and non-duplicated household totals.','Maintain organization-scoped relationships with referential integrity.','Household totals count each authoritative activity once.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-history','module-donor-crm','Giving and participation history','Donations, auctions, wins, payments, tickets, attendance, sponsorships, and communications.','Reuse Gather transaction and event sources rather than creating a parallel ledger.','Financial summaries reconcile to authoritative transaction activity.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-import','module-donor-crm','Import, export, duplicates, and merging','Mapped CSV preview, validation, matching, review, organization exports, and audited merges.','Imported contacts never become automatically subscribed to marketing.','Duplicate review is non-destructive until an authorized merge.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-tasks','module-donor-crm','Tasks, reminders, and notes','Manual and limited idempotent event-triggered follow-up tasks.','Support due dates, assignment, completion, notes, and related contact/opportunity records.','Automation creates internal review tasks only and never external sends.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-pipeline','module-donor-crm','Fundraising opportunity pipeline','Major gift, sponsorship, and auction-item donation opportunities.','Use Prospect, Contacted, Committed, Fulfilled, and Thanked stages with factual amounts and next steps.','Stage changes are authorized and audited.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-preferences','module-donor-crm','Communication preferences','Email and SMS consent, opt-out, suppression, source, and timestamp.','Share email preference truth with Email Marketing and never override complaints or unsubscribe suppression.','Suppressed contacts remain ineligible for marketing.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-attachments','module-donor-crm','Private contact attachments','Authorized PDF, image, and text attachments stored privately.','Validate type and size and return short-lived signed access URLs only after organization access checks.','Cross-organization attachment access is denied.','In Progress','Approved','system',1795086400000,1795086400000),
('crm-feature-reports','module-donor-crm','Fundraising and retention reports','Factual revenue, donor, retention, attendance, auction, sponsorship, and outstanding-balance reporting.','Document definitions and prevent double counting.','No speculative metrics are presented as measured results.','In Progress','Approved','system',1795086400000,1795086400000);
